		// diagram is outside our subset (subgraph, sequence diagram, prose).
		if isBailDirective(line) || strings.Contains(line, "&") {
			return nil, nil, false
		}

		lineNodes, lineEdges, ok := parseLine(line)
		if !ok {
			return nil, nil, false
		}
		sawAnyContent = true
		for _, d := range lineNodes {
			ensure(d.id, d.label)
		}
		for _, e := range lineEdges {
			ensure(e.from, e.from)
			ensure(e.to, e.to)
			edges = append(edges, e)
		}
	}

	if !sawFlowchart || !sawAnyContent || len(nodes) == 0 {
		return nil, nil, false
	}
	return nodes, edges, true
}

// parseLine parses one structural line into the nodes it declares and the
// edges it forms. A line is either a bare node declaration (`A[Label]`) or a
// chain of nodes joined by links (`A --> B --> C`).
func parseLine(line string) ([]node, []edge, bool) {
	locs := linkRe.FindAllStringSubmatchIndex(line, -1)
	if len(locs) == 0 {
		// No link: must be a standalone node declaration.
		n, ok := parseNodeToken(line)
		if !ok {
			return nil, nil, false
		}
		return []node{n}, nil, true
	}

	// Node tokens are the segments between (and around) the link matches.
	var tokens []node
	prev := 0
	var labels []string
	for _, loc := range locs {
		seg := line[prev:loc[0]]
		n, ok := parseNodeToken(seg)
		if !ok {
			return nil, nil, false
		}
