// nodes and returns the nodes in path order. It returns ok=false for
// branches (out-degree > 1), fan-in (in-degree > 1), cycles, and
// disconnected components — anything that isn't one unambiguous chain.
func linearOrder(nodes map[string]*node, edges []edge) ([]node, bool) {
	// Single node, no edges: a degenerate but valid one-box diagram.
	if len(nodes) == 1 && len(edges) == 0 {
		for _, n := range nodes {
			return []node{*n}, true
		}
	}
	if len(edges) != len(nodes)-1 {
		return nil, false
	}

	outTo := map[string]string{}
	indeg := map[string]int{}
	outdeg := map[string]int{}
	for _, e := range edges {
		if _, dup := outTo[e.from]; dup {
			return nil, false // out-degree > 1 → branch
		}
		outTo[e.from] = e.to
		outdeg[e.from]++
		indeg[e.to]++
		if indeg[e.to] > 1 {
			return nil, false // in-degree > 1 → fan-in
		}
	}

