input.content:
// Package mermaidascii renders a constrained subset of Mermaid flowcharts —
// a single rooted tree (a linear chain or a branching tree, in-degree ≤ 1
// per node) — as aligned Unicode box diagrams for terminal display.
//
// Investigation findings are authored in Mermaid (which renders natively on
// GitHub and in docs), but the terminal renderer (glamour) shows a
// ```mermaid block as raw source. This package converts the shapes the
// investigation prompt steers agents toward — a flow that may fork into
// success/failure paths — into a real diagram, while deliberately refusing
// anything outside a tree (DAG joins where two arrows enter one node,
// cycles, subgraphs, unrecognized syntax) so callers fall back to the raw
// Mermaid source rather than rendering a misleading partial picture.
//
// Layout is left-to-right: a node's column is its depth from the root, and
// siblings stack vertically. Branch points are routed with box-drawing
// junctions in the gap between columns. Because every node has at most one
// parent, the layout is unambiguous and always correctly aligned.
package mermaidascii

import (
	"math"
	"regexp"
	"strings"

	"github.com/mattn/go-runewidth"
)

// edge is a directed link from one node id to another, with an optional
// label parsed from `-->|label|` syntax.
type edge struct {
	from  string
	to    string
	label string
}

// vertex is a laid-out flowchart node: its label (already split into display
// lines), box dimensions, tree position, and children in declared order.
type vertex struct {
	id       string
	lines    []string
	w, h     int // box width/height including borders
	col      int
	children []string
}

// linkRe matches a Mermaid link operator with an optional `|label|`. The
// surrounding whitespace is consumed so the text between matches is exactly
// the node tokens. Inline-label syntax (`A -- text --> B`) is intentionally
// unsupported and causes a parse failure → raw fallback.
var linkRe = regexp.MustCompile(`\s*(?:-->|---|==>|===|-\.->|-\.-)\s*(?:\|([^|]*)\|)?\s*`)

// nodeRe matches a single node token: an id followed by an optional shape
// wrapper. We extract the id and the inner label regardless of shape, and
// always render a rectangle.
var nodeRe = regexp.MustCompile(`^([A-Za-z0-9_]+)\s*(\[\[.*\]\]|\(\(.*\)\)|\[.*\]|\(.*\)|\{.*\}|>.*\])?$`)

// headerRe matches the `flowchart`/`graph` declaration line.
var headerRe = regexp.MustCompile(`^(?:flowchart|graph)\b`)

// brRe matches Mermaid line breaks in labels (`<br>`, `<br/>`, `<br />`).
var brRe = regexp.MustCompile(`(?i)<br\s*/?>`)

// RenderFlowchart renders src as an aligned Unicode box diagram and returns
// ok=true, or returns ok=false when src is not a single rooted tree it can
// render. On ok=false the caller should show the raw Mermaid source.
func RenderFlowchart(src string) (string, bool) {
	nodes, edges, ok := parse(src)
	if !ok {
		return "", false
	}
	root, verts, ok := buildTree(nodes, edges)
	if !ok {
		return "", false
	}
	return renderTree(root, verts, edges), true
}

// parse reads the flowchart body into node labels (keyed by id) and edges. It
// returns ok=false for any construct outside the supported subset (subgraphs,
// `&` multi-edge, non-flowchart diagrams, or any unrecognized non-blank
// line).
func parse(src string) (map[string]string, []edge, bool) {
	labels := map[string]string{}
	var edges []edge
	sawFlowchart := false
	sawAnyContent := false

	ensure := func(id, label string) {
		cur, exists := labels[id]
		if !exists {
			labels[id] = label
			return
		}
		// A later bracketed reference defines the label; bare references
		// (label == id) never overwrite a real label.
		if label != id && cur == id {
			labels[id] = label
		}
	}

	for raw := range strings.SplitSeq(src, "\n") {
		line := strings.TrimSpace(stripComment(raw))
		if line == "" {
			continue
		}
		if headerRe.MatchString(line) {
			sawFlowchart = true
			continue
		}
		if isIgnorableDirective(line) {
			continue
		}
		if isBailDirective(line) || strings.Contains(line, "&") {
			return nil, nil, false
		}

		lineNodes, lineEdges, ok := parseLine(line)
		if !ok {
			return nil, nil, false
		}
		sawAnyContent = true
		for id, label := range lineNodes {
			ensure(id, label)
		}
		for _, e := range lineEdges {
			ensure(e.from, e.from)
			ensure(e.to, e.to)
			edges = append(edges, e)
		}
	}

	if !sawFlowchart || !sawAnyContent || len(labels) == 0 {
		return nil, nil, false
	}
	return labels, edges, true
}

// parseLine parses one structural line into the node labels it declares and
// the edges it forms. A line is either a bare node declaration (`A[Label]`)
// or a chain of nodes joined by links (`A --> B --> C`).
func parseLine(line string) (map[string]string, []edge, bool) {
	locs := linkRe.FindAllStringSubmatchIndex(line, -1)
	nodes := map[string]string{}
	if len(locs) == 0 {
		id, label, ok := parseNodeToken(line)
		if !ok {
			return nil, nil, false
		}
		nodes[id] = label
		return nodes, nil, true
	}

	type tok struct{ id, label string }
	var tokens []tok
	var edgeLabels []string
	prev := 0
	for _, loc := range locs {
		id, label, ok := parseNodeToken(line[prev:loc[0]])
		if !ok {
			return nil, nil, false
		}
		tokens = append(tokens, tok{id, label})
		nodes[id] = label
		el := ""
		if loc[2] >= 0 {
			el = cleanEdgeLabel(line[loc[2]:loc[3]])
		}
		edgeLabels = append(edgeLabels, el)
		prev = loc[1]
	}
	id, label, ok := parseNodeToken(line[prev:])
	if !ok {
		return nil, nil, false
	}
	tokens = append(tokens, tok{id, label})
	nodes[id] = label

	edges := make([]edge, 0, len(tokens)-1)
	for i := 0; i+1 < len(tokens); i++ {
		edges = append(edges, edge{from: tokens[i].id, to: tokens[i+1].id, label: edgeLabels[i]})
	}
	return nodes, edges, true
}

// parseNodeToken extracts the id and label from a single node token, peeling
// the shape wrapper and surrounding quotes. Returns ok=false on anything that
// isn't a lone node reference.
func parseNodeToken(s string) (id, label string, ok bool) {
	s = strings.TrimSpace(s)
	m := nodeRe.FindStringSubmatch(s)
	if m == nil {
		return "", "", false
	}
	id = m[1]
	label = id
	if shape := m[2]; shape != "" {
		inner := strings.TrimSpace(unwrapShape(shape))
		inner = strings.TrimSpace(strings.Trim(inner, `"`))
		if inner != "" {
			label = inner
		}
	}
	return id, label, true
}

// unwrapShape strips the outer bracket pair(s) from a shape wrapper, leaving
// the inner label text.
func unwrapShape(shape string) string {
	for _, pair := range []struct{ open, close string }{
		{"[[", "]]"}, {"((", "))"}, {"[", "]"}, {"(", ")"}, {"{", "}"},
	} {
		if strings.HasPrefix(shape, pair.open) && strings.HasSuffix(shape, pair.close) {
			return strings.TrimSuffix(strings.TrimPrefix(shape, pair.open), pair.close)
		}
	}
	if strings.HasPrefix(shape, ">") && strings.HasSuffix(shape, "]") {
		return strings.TrimSuffix(strings.TrimPrefix(shape, ">"), "]")
	}
	return shape
}

// buildTree validates that the graph is a single rooted tree and returns the
// root id and laid-out vertices (label lines + box size + column depth +
// child order). It returns ok=false for fan-in (in-degree > 1), multiple or
// missing roots, cycles, and disconnected components.
func buildTree(labels map[string]string, edges []edge) (string, map[string]*vertex, bool) {
	verts := make(map[string]*vertex, len(labels))
	for id, label := range labels {
		lines := splitLabel(label, id)
		verts[id] = &vertex{id: id, lines: lines, w: boxWidth(lines), h: len(lines) + 2}
	}

	indeg := map[string]int{}
	for _, e := range edges {
		indeg[e.to]++
		if indeg[e.to] > 1 {
			return "", nil, false // fan-in → not a tree
		}
		verts[e.from].children = append(verts[e.from].children, e.to)
	}

	var root string
	roots := 0
	for id := range verts {
		if indeg[id] == 0 {
			roots++
			root = id
		}
	}
	if roots != 1 {
		return "", nil, false
	}

	// BFS from the root assigns column depth and proves the graph is a single
	// connected, acyclic component (every node reached exactly once).
	verts[root].col = 0
	visited := map[string]bool{root: true}
	queue := []string{root}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		for _, c := range verts[cur].children {
			if visited[c] {
				return "", nil, false // cycle
			}
			visited[c] = true
			verts[c].col = verts[cur].col + 1
			queue = append(queue, c)
		}
	}
	if len(visited) != len(verts) {
		return "", nil, false // disconnected
	}
	return root, verts, true
}

// line-drawing direction bits for junction glyph selection.
const (
	up uint8 = 1 << iota
	down
	left
	right
)

// renderTree lays the tree out on a character canvas and returns the trimmed
// diagram. Columns are spaced by box width plus the routing gap; siblings are
// stacked vertically and a parent is centered on its children.
func renderTree(root string, verts map[string]*vertex, edges []edge) string {
	edgeLabel := func(from, to string) string {
		for _, e := range edges {
			if e.from == from && e.to == to {
				return e.label
			}
		}
		return ""
	}

	maxCol := 0
	maxH := 0
	for _, v := range verts {
		maxCol = max(maxCol, v.col)
		maxH = max(maxH, v.h)
	}

	// Column geometry: colX is each column's left edge; busX is the routing
	// column in the gap to the right where branch arrows turn.
	maxW := make([]int, maxCol+1)
	maxRun := make([]int, maxCol+1) // widest child-entry arrow (incl. label)
	for _, v := range verts {
		maxW[v.col] = max(maxW[v.col], v.w)
		for _, c := range v.children {
			maxRun[v.col] = max(maxRun[v.col], runewidth.StringWidth(childRun(edgeLabel(v.id, c))))
		}
	}
	colX := make([]int, maxCol+2)
	busX := make([]int, maxCol+1)
	for c := 0; c <= maxCol; c++ {
		busX[c] = colX[c] + maxW[c] + 1
		colX[c+1] = busX[c] + 1 + maxRun[c]
	}

	// Vertical tracks: leaves get successive slots; a parent sits at the
	// midpoint of its children. slotH keeps every box aligned to a grid.
	slotH := maxH + 1
	track := map[string]float64{}
	next := 0.0
	var assign func(id string)
	assign = func(id string) {
		ch := verts[id].children
		if len(ch) == 0 {
			track[id] = next
			next++
			return
		}
		for _, c := range ch {
			assign(c)
		}
		track[id] = (track[ch[0]] + track[ch[len(ch)-1]]) / 2
	}
	assign(root)

	centerRow := func(id string) int {
		return int(math.Round(track[id]*float64(slotH))) + slotH/2
	}
	boxTop := func(id string) int { return centerRow(id) - verts[id].h/2 }

	width, height := 0, 0
	for id, v := range verts {
		width = max(width, colX[v.col]+v.w)
		height = max(height, boxTop(id)+v.h)
	}

	cv := newCanvas(width, height)
	mask := make([][]uint8, height)
	for i := range mask {
		mask[i] = make([]uint8, width)
	}

	// Boxes.
	for id, v := range verts {
		x, top := colX[v.col], boxTop(id)
		inner := v.w - 2
		bar := strings.Repeat("─", inner)
		cv.write(x, top, "┌"+bar+"┐")
		for i, ln := range v.lines {
			cv.write(x, top+1+i, "│"+pad(ln, inner)+"│")
		}
		cv.write(x, top+v.h-1, "└"+bar+"┘")
	}

	// Edges: parent-exit horizontal, vertical bus, child-entry horizontal.
	addMask := func(x, y int, bits uint8) {
		if y >= 0 && y < height && x >= 0 && x < width {
			mask[y][x] |= bits
		}
	}
	type entry struct {
		row, xEnd int
		label     string
	}
	var entries []entry
	for id, v := range verts {
		if len(v.children) == 0 {
			continue
		}
		yP := centerRow(id)
		xR := colX[v.col] + v.w // first cell right of the parent box
		xB := busX[v.col]
		for x := xR; x < xB; x++ {
			addMask(x, yP, left|right)
		}
		ys := make([]int, len(v.children))
		for i, c := range v.children {
			ys[i] = centerRow(c)
		}
		busTop, busBot := yP, yP
		for _, y := range ys {
			busTop = min(busTop, y)
			busBot = max(busBot, y)
		}
		for y := busTop; y <= busBot; y++ {
			var bits uint8
			if y > busTop {
				bits |= up
			}
			if y < busBot {
				bits |= down
			}
			if y == yP {
				bits |= left
			}
			for _, cy := range ys {
				if y == cy {
					bits |= right
				}
			}
			addMask(xB, y, bits)
		}
		for i, c := range v.children {
			yc := ys[i]
			xEnd := colX[verts[c].col] - 1 // cell just left of the child box
			for x := xB + 1; x <= xEnd; x++ {
				addMask(x, yc, left|right)
			}
			entries = append(entries, entry{row: yc, xEnd: xEnd, label: edgeLabel(id, c)})
		}
	}

	// Paint mask glyphs on empty cells (boxes already drawn take priority).
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			if mask[y][x] != 0 && cv.rows[y][x] == ' ' {
				cv.rows[y][x] = glyph(mask[y][x])
			}
		}
	}
	// Arrowheads and inline edge labels last so they sit on top of the line.
	for _, e := range entries {
		cv.rows[e.row][e.xEnd] = '>'
		if e.label != "" {
			start := busX[verts[root].col] // unused placeholder; recomputed below
			_ = start
			placeLabel(cv, e.row, e.xEnd, e.label)
		}
	}

	return cv.String()
}

// placeLabel centers label on the dashed run that ends (just before the
// arrowhead) at xEnd, overwriting the middle dashes. The gap width was sized
// to fit the widest label in the column, so it always fits.
func placeLabel(cv *canvas, row, xEnd int, label string) {
	w := runewidth.StringWidth(label)
	// Find the dashed run extent to the left of the arrowhead.
	start := xEnd - 1
	for start > 0 && cv.rows[row][start-1] == '─' {
		start--
	}
	runLen := xEnd - start // dashes before the arrowhead
	off := start + (runLen-w)/2
	if off < start {
		off = start
	}
	cv.write(off, row, label)
}

// childRun is the dashed arrow segment (with optional inline label) drawn
// into a child box. Used only to size the column gap.
func childRun(label string) string {
	if label == "" {
		return "──>"
	}
	return "──" + label + "──>"
}

// glyph maps a set of connection directions to a box-drawing character.
func glyph(m uint8) rune {
	switch m {
	case up | down:
		return '│'
	case left | right:
		return '─'
	case up | right:
		return '└'
	case up | left:
		return '┘'
	case down | right:
		return '┌'
	case down | left:
		return '┐'
	case up | down | right:
		return '├'
	case up | down | left:
		return '┤'
	case left | right | down:
		return '┬'
	case left | right | up:
		return '┴'
	case up | down | left | right:
		return '┼'
	case up, down:
		return '│'
	case left, right:
		return '─'
	}
	return ' '
}

// canvas is a fixed-size rune grid painted by the tree renderer.
type canvas struct {
	rows [][]rune
	w    int
}

func newCanvas(w, h int) *canvas {
	rows := make([][]rune, h)
	for i := range rows {
		rows[i] = make([]rune, w)
		for j := range rows[i] {
			rows[i][j] = ' '
		}
	}
	return &canvas{rows: rows, w: w}
}

// write paints s starting at (x,y), advancing by each rune's display width so
// wide glyphs don't shift later columns.
func (c *canvas) write(x, y int, s string) {
	if y < 0 || y >= len(c.rows) {
		return
	}
	for _, r := range s {
		if x >= 0 && x < c.w {
			c.rows[y][x] = r
		}
		x += runewidth.RuneWidth(r)
	}
}

// String renders the canvas, trimming trailing spaces per line and dropping
// fully-blank leading/trailing lines.
func (c *canvas) String() string {
	lines := make([]string, len(c.rows))
	for i, row := range c.rows {
		lines[i] = strings.TrimRight(string(row), " ")
	}
	start, end := 0, len(lines)
	for start < end && lines[start] == "" {
		start++
	}
	for end > start && lines[end-1] == "" {
		end--
	}
	return strings.Join(lines[start:end], "\n")
}

// boxWidth is the rendered box width (widest line + 1 space padding each side
// + 2 borders).
func boxWidth(lines []string) int {
	w := 0
	for _, ln := range lines {
		w = max(w, runewidth.StringWidth(ln))
	}
	return w + 4
}

// pad centers-left a label line within innerWidth cells (one leading space,
// trailing spaces to fill), accounting for display width.
func pad(s string, innerWidth int) string {
	gap := innerWidth - runewidth.StringWidth(s) - 1
	if gap < 0 {
		gap = 0
	}
	return " " + s + strings.Repeat(" ", gap)
}

// splitLabel splits a node label on Mermaid line breaks into display lines,
// falling back to the id when empty.
func splitLabel(label, id string) []string {
	var out []string
	for _, p := range brRe.Split(label, -1) {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	if len(out) == 0 {
		return []string{id}
	}
	return out
}

// cleanEdgeLabel flattens an edge label to a single line (line breaks and
// runs of whitespace collapse to single spaces).
func cleanEdgeLabel(s string) string {
	return strings.Join(strings.Fields(brRe.ReplaceAllString(s, " ")), " ")
}

// displayWidth reports the terminal cell width of s. Exposed for tests that
// assert row alignment.
func displayWidth(s string) int { return runewidth.StringWidth(s) }

func stripComment(line string) string {
	if before, _, found := strings.Cut(line, "%%"); found {
		return before
	}
	return line
}

// isIgnorableDirective reports lines we can safely skip without affecting the
// structure (styling/interaction directives carry no structural meaning).
func isIgnorableDirective(line string) bool {
	for _, p := range []string{"classDef", "class ", "style ", "linkStyle", "click ", "direction "} {
		if strings.HasPrefix(line, p) {
			return true
		}
	}
	return false
}

// isBailDirective reports constructs that put the diagram outside our subset.
func isBailDirective(line string) bool {
	for _, p := range []string{"subgraph", "end", "sequenceDiagram", "stateDiagram", "erDiagram", "gantt", "pie", "journey"} {
		if line == p || strings.HasPrefix(line, p+" ") {
			return true
		}
	}
	return false
}

var mermaidBlockRe = regexp.MustCompile("(?s)```mermaid[ \t]*\r?\n(.*?)\r?\n```")

// TransformMarkdown replaces each ```mermaid fenced block whose body is a
// renderable tree flowchart with a fenced plain-text block containing the box
// diagram. Blocks it cannot render are left exactly as-is, so the raw Mermaid
// survives for GitHub/doc rendering and for piped output.
func TransformMarkdown(md string) string {
	return mermaidBlockRe.ReplaceAllStringFunc(md, func(block string) string {
		m := mermaidBlockRe.FindStringSubmatch(block)
		if m == nil {
			return block
		}
		ascii, ok := RenderFlowchart(m[1])
		if !ok {
			return block
		}
		return "```\n" + ascii + "\n```"
	})
}

