package mermaidascii

import (
	"strings"
	"testing"
)

// renderable cases: a single linear left-to-right chain. We assert the
// labels appear in order and the output has the three box rows; exact
// spacing is an implementation detail we don't pin.
func TestRenderFlowchart_RenderableChains(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name      string
		src       string
		wantOrder []string // labels expected left-to-right
		wantEdge  []string // substrings expected somewhere (e.g. edge labels)
	}{
		{
			name:      "two node bracket labels",
			src:       "flowchart LR\n  A[Producer] --> B[Consumer]",
			wantOrder: []string{"Producer", "Consumer"},
		},
		{
			name:      "edge label",
			src:       "flowchart LR\n  A[Producer] -->|enqueue| B[Consumer]",
			wantOrder: []string{"Producer", "Consumer"},
			wantEdge:  []string{"enqueue"},
		},
		{
			name: "multi node across lines, order follows the path not declaration",
			// declared out of flow order on purpose
			src: "flowchart LR\n" +
				"  C[Consumer] --> R[Retries]\n" +
				"  P[Producer] --> I[Input]\n" +
				"  I --> C\n",
			wantOrder: []string{"Producer", "Input", "Consumer", "Retries"},
		},
		{
			name:      "chained on one line",
			src:       "flowchart LR\n  A --> B --> C",
			wantOrder: []string{"A", "B", "C"},
		},
		{
			name:      "bare ids no brackets",
			src:       "graph LR\n  A --> B",
			wantOrder: []string{"A", "B"},
		},
		{
			name:      "rounded and diamond shapes",
			src:       "flowchart LR\n  A(Producer) --> B{Decision}",
			wantOrder: []string{"Producer", "Decision"},
		},
		{
			name:      "TD direction still renders horizontally",
			src:       "flowchart TD\n  A[One] --> B[Two]",
			wantOrder: []string{"One", "Two"},
		},
		{
			name:      "single node only",
			src:       "flowchart LR\n  A[Solo]",
			wantOrder: []string{"Solo"},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			out, ok := RenderFlowchart(tc.src)
			if !ok {
				t.Fatalf("expected renderable, got ok=false for:\n%s", tc.src)
			}
			if strings.Count(out, "\n") < 2 {
				t.Errorf("expected at least 3 box rows, got:\n%s", out)
			}
			// labels appear in left-to-right order: their first index in
			// the output must be strictly increasing.
			prev := -1
			for _, label := range tc.wantOrder {
				idx := strings.Index(out, label)
				if idx < 0 {
					t.Fatalf("label %q missing from output:\n%s", label, out)
				}
				if idx <= prev {
					t.Errorf("label %q out of order in output:\n%s", label, out)
				}
				prev = idx
			}
			for _, sub := range tc.wantEdge {
				if !strings.Contains(out, sub) {
					t.Errorf("expected %q in output:\n%s", sub, out)
				}
			}
		})
	}
}

// box rows must be width-aligned: every line in the rendered output has the
// same display width. Misalignment is the whole reason agents' hand-drawn
// ASCII looked terrible, so this is the core guarantee.
func TestRenderFlowchart_RowsAreAligned(t *testing.T) {
	t.Parallel()

	src := "flowchart LR\n  A[Producer] -->|enqueue| B[Input queue] --> C[Consumer]"
	out, ok := RenderFlowchart(src)
	if !ok {
		t.Fatalf("expected renderable")
	}
	lines := strings.Split(strings.TrimRight(out, "\n"), "\n")
	if len(lines) != 3 {
		t.Fatalf("expected exactly 3 rows, got %d:\n%s", len(lines), out)
	}
	want := displayWidth(lines[0])
	for i, ln := range lines {
		if got := displayWidth(ln); got != want {
			t.Errorf("row %d width %d != %d (rows not aligned):\n%s", i, got, want, out)
		}
	}
}

// not-renderable cases must return ok=false so the caller can fall back to
// the raw mermaid source. We never render a misleading partial diagram.
func TestRenderFlowchart_FallsBack(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name string
		src  string
	}{
		{name: "back edge / cycle", src: "flowchart LR\n A --> B\n B --> A"},
		{name: "branch out", src: "flowchart LR\n A --> B\n A --> C"},
		{name: "fan in", src: "flowchart LR\n A --> C\n B --> C"},
		{name: "two disconnected edges", src: "flowchart LR\n A --> B\n C --> D"},
		{name: "subgraph", src: "flowchart LR\n subgraph S\n A --> B\n end"},
		{name: "ampersand multi target", src: "flowchart LR\n A --> B & C"},
		{name: "unrecognized line", src: "flowchart LR\n A --> B\n this is not valid"},
		{name: "no edges multiple nodes", src: "flowchart LR\n A[One]\n B[Two]"},
		{name: "empty", src: ""},
		{name: "header only", src: "flowchart LR"},
		{name: "not a flowchart", src: "sequenceDiagram\n Alice->>Bob: hi"},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			if out, ok := RenderFlowchart(tc.src); ok {
				t.Errorf("expected ok=false (fallback) for %q, got:\n%s", tc.name, out)
			}
		})
	}
}

func TestTransformMarkdown(t *testing.T) {
	t.Parallel()

	t.Run("replaces renderable block, drops mermaid fence", func(t *testing.T) {
		t.Parallel()

		md := "## System\n\n```mermaid\nflowchart LR\n A[Producer] --> B[Consumer]\n```\n\nrest\n"
		out := TransformMarkdown(md)
		if strings.Contains(out, "```mermaid") {
			t.Errorf("expected mermaid fence removed, got:\n%s", out)
		}
		if !strings.Contains(out, "Producer") || !strings.Contains(out, "Consumer") {
			t.Errorf("expected rendered labels retained, got:\n%s", out)
		}
		if !strings.Contains(out, "## System") || !strings.Contains(out, "rest") {
			t.Errorf("expected surrounding markdown preserved, got:\n%s", out)
		}
		// box-drawing char proves it rendered to a diagram, not left as code.
		if !strings.Contains(out, "┌") {
			t.Errorf("expected a rendered box, got:\n%s", out)
		}
	})

	t.Run("leaves unrenderable mermaid block unchanged", func(t *testing.T) {
		t.Parallel()

		md := "```mermaid\nflowchart LR\n A --> B\n B --> A\n```\n"
		out := TransformMarkdown(md)
		if out != md {
			t.Errorf("expected unrenderable block left intact, got:\n%s", out)
		}
	})

	t.Run("leaves non-mermaid content untouched", func(t *testing.T) {
		t.Parallel()

		md := "# Title\n\nSome text and a ```go\nfunc x(){}\n``` block.\n"
		out := TransformMarkdown(md)
		if out != md {
			t.Errorf("expected non-mermaid content untouched, got:\n%s", out)
		}
	})

	t.Run("handles multiple mermaid blocks independently", func(t *testing.T) {
		t.Parallel()

		md := "```mermaid\nflowchart LR\n A[X] --> B[Y]\n```\n\nmid\n\n```mermaid\nflowchart LR\n P --> Q\n Q --> P\n```\n"
		out := TransformMarkdown(md)
		// first (renderable) gets transformed, second (cycle) stays.
		if strings.Count(out, "```mermaid") != 1 {
			t.Errorf("expected exactly one mermaid fence remaining, got:\n%s", out)
		}
		if !strings.Contains(out, "┌") {
			t.Errorf("expected first block rendered, got:\n%s", out)
		}
	})
}

