1	// Package mermaidascii renders a constrained subset of Mermaid flowcharts —
2	// a single rooted tree (a linear chain or a branching tree, in-degree ≤ 1
3	// per node) — as aligned Unicode box diagrams for terminal display.
4	//
5	// Investigation findings are authored in Mermaid (which renders natively on
6	// GitHub and in docs), but the terminal renderer (glamour) shows a
7	// ```mermaid block as raw source. This package converts the shapes the
8	// investigation prompt steers agents toward — a flow that may fork into
9	// success/failure paths — into a real diagram, while deliberately refusing
10	// anything outside a tree (DAG joins where two arrows enter one node,
11	// cycles, subgraphs, unrecognized syntax) so callers fall back to the raw
12	// Mermaid source rather than rendering a misleading partial picture.
13	//
14	// Layout is left-to-right: a node's column is its depth from the root, and
15	// siblings stack vertically. Branch points are routed with box-drawing
16	// junctions in the gap between columns. Because every node has at most one
17	// parent, the layout is unambiguous and always correctly aligned.
18	package mermaidascii
19	
20	import (
21		"math"
22		"regexp"
23		"strings"
24	
25		"github.com/mattn/go-runewidth"
26	)
27	
28	// edge is a directed link from one node id to another, with an optional
29	// label parsed from `-->|label|` syntax.
30	type edge struct {
31		from  string
32		to    string
33		label string
34	}
35	
36	// vertex is a laid-out flowchart node: its label (already split into display
37	// lines), box dimensions, tree position, and children in declared order.
38	type vertex struct {
39		id       string
40		lines    []string
41		w, h     int // box width/height including borders
42		col      int
43		children []string
44	}
45	
46	// linkRe matches a Mermaid link operator with an optional `|label|`. The
47	// surrounding whitespace is consumed so the text between matches is exactly
48	// the node tokens. Inline-label syntax (`A -- text --> B`) is intentionally
49	// unsupported and causes a parse failure → raw fallback.
50	var linkRe = regexp.MustCompile(`\s*(?:-->|---|==>|===|-\.->|-\.-)\s*(?:\|([^|]*)\|)?\s*`)
51	
52	// nodeRe matches a single node token: an id followed by an optional shape
53	// wrapper. We extract the id and the inner label regardless of shape, and
54	// always render a rectangle.
55	var nodeRe = regexp.MustCompile(`^([A-Za-z0-9_]+)\s*(\[\[.*\]\]|\(\(.*\)\)|\[.*\]|\(.*\)|\{.*\}|>.*\])?$`)
56	
57	// headerRe matches the `flowchart`/`graph` declaration line.
58	var headerRe = regexp.MustCompile(`^(?:flowchart|graph)\b`)
59	
60	// brRe matches Mermaid line breaks in labels (`<br>`, `<br/>`, `<br />`).
61	var brRe = regexp.MustCompile(`(?i)<br\s*/?>`)
62	
63	// RenderFlowchart renders src as an aligned Unicode box diagram and returns
64	// ok=true, or returns ok=false when src is not a single rooted tree it can
65	// render. On ok=false the caller should show the raw Mermaid source.
66	func RenderFlowchart(src string) (string, bool) {
67		nodes, edges, ok := parse(src)
68		if !ok {
69			return "", false
70		}
71		root, verts, ok := buildTree(nodes, edges)
72		if !ok {
73			return "", false
74		}
75		return renderTree(root, verts, edges), true
76	}
77	
78	// parse reads the flowchart body into node labels (keyed by id) and edges. It
79	// returns ok=false for any construct outside the supported subset (subgraphs,
80	// `&` multi-edge, non-flowchart diagrams, or any unrecognized non-blank
81	// line).
82	func parse(src string) (map[string]string, []edge, bool) {
83		labels := map[string]string{}
84		var edges []edge
85		sawFlowchart := false
86		sawAnyContent := false
87	
88		ensure := func(id, label string) {
89			cur, exists := labels[id]
90			if !exists {
91				labels[id] = label
92				return
93			}
94			// A later bracketed reference defines the label; bare references
95			// (label == id) never overwrite a real label.
96			if label != id && cur == id {
97				labels[id] = label
98			}
99		}
100	
101		for raw := range strings.SplitSeq(src, "\n") {
102			line := strings.TrimSpace(stripComment(raw))
103			if line == "" {
104				continue
105			}
106			if headerRe.MatchString(line) {
107				sawFlowchart = true
108				continue
109			}
110			if isIgnorableDirective(line) {
111				continue
112			}
113			if isBailDirective(line) || strings.Contains(line, "&") {
114				return nil, nil, false
115			}
116	
117			lineNodes, lineEdges, ok := parseLine(line)
118			if !ok {
119				return nil, nil, false
120			}
121			sawAnyContent = true
122			for id, label := range lineNodes {
123				ensure(id, label)
124			}
125			for _, e := range lineEdges {
126				ensure(e.from, e.from)
127				ensure(e.to, e.to)
128				edges = append(edges, e)
129			}
130		}
131	
132		if !sawFlowchart || !sawAnyContent || len(labels) == 0 {
133			return nil, nil, false
134		}
135		return labels, edges, true
136	}
137	
138	// parseLine parses one structural line into the node labels it declares and
139	// the edges it forms. A line is either a bare node declaration (`A[Label]`)
140	// or a chain of nodes joined by links (`A --> B --> C`).
141	func parseLine(line string) (map[string]string, []edge, bool) {
142		locs := linkRe.FindAllStringSubmatchIndex(line, -1)
143		nodes := map[string]string{}
144		if len(locs) == 0 {
145			id, label, ok := parseNodeToken(line)
146			if !ok {
147				return nil, nil, false
148			}
149			nodes[id] = label
150			return nodes, nil, true
151		}
152	
153		type tok struct{ id, label string }
154		var tokens []tok
155		var edgeLabels []string
156		prev := 0
157		for _, loc := range locs {
158			id, label, ok := parseNodeToken(line[prev:loc[0]])
159			if !ok {
160				return nil, nil, false
161			}
162			tokens = append(tokens, tok{id, label})
163			nodes[id] = label
164			el := ""
165			if loc[2] >= 0 {
166				el = cleanEdgeLabel(line[loc[2]:loc[3]])
167			}
168			edgeLabels = append(edgeLabels, el)
169			prev = loc[1]
170		}
171		id, label, ok := parseNodeToken(line[prev:])
172		if !ok {
173			return nil, nil, false
174		}
175		tokens = append(tokens, tok{id, label})
176		nodes[id] = label
177	
178		edges := make([]edge, 0, len(tokens)-1)
179		for i := 0; i+1 < len(tokens); i++ {
180			edges = append(edges, edge{from: tokens[i].id, to: tokens[i+1].id, label: edgeLabels[i]})
181		}
182		return nodes, edges, true
183	}
184	
185	// parseNodeToken extracts the id and label from a single node token, peeling
186	// the shape wrapper and surrounding quotes. Returns ok=false on anything that
187	// isn't a lone node reference.
188	func parseNodeToken(s string) (id, label string, ok bool) {
189		s = strings.TrimSpace(s)
190		m := nodeRe.FindStringSubmatch(s)
191		if m == nil {
192			return "", "", false
193		}
194		id = m[1]
195		label = id
196		if shape := m[2]; shape != "" {
197			inner := strings.TrimSpace(unwrapShape(shape))
198			inner = strings.TrimSpace(strings.Trim(inner, `"`))
199			if inner != "" {
200				label = inner
201			}
202		}
203		return id, label, true
204	}
205	
206	// unwrapShape strips the outer bracket pair(s) from a shape wrapper, leaving
207	// the inner label text.
208	func unwrapShape(shape string) string {
209		for _, pair := range []struct{ open, close string }{
210			{"[[", "]]"}, {"((", "))"}, {"[", "]"}, {"(", ")"}, {"{", "}"},
211		} {
212			if strings.HasPrefix(shape, pair.open) && strings.HasSuffix(shape, pair.close) {
213				return strings.TrimSuffix(strings.TrimPrefix(shape, pair.open), pair.close)
214			}
215		}
216		if strings.HasPrefix(shape, ">") && strings.HasSuffix(shape, "]") {
217			return strings.TrimSuffix(strings.TrimPrefix(shape, ">"), "]")
218		}
219		return shape
220	}
